  typedef StructuredNoteHistogramBinT NativeTableType;
  typedef StructuredNoteHistogramBinBuilder Builder;
  enum FlatBuffersVTableOffset FLATBUFFERS_VTABLE_UNDERLYING_TYPE {
    VT_LOWER = 4,
    VT_UPPER = 6,
    VT_PATHS = 8
  };
  /// Lower edge (fraction of notional), inclusive.
  double lower() const {
    return GetField<double>(VT_LOWER, 0.0);
  }
  /// Upper edge, exclusive (inclusive for the last bin).
  double upper() const {
    return GetField<double>(VT_UPPER, 0.0);
  }
  /// Simulated paths in the bin; the bins sum to the result's `paths`.
  uint32_t paths() const {
    return GetField<uint32_t>(VT_PATHS, 0);
  }
  bool Verify(::flatbuffers::Verifier &verifier) const {
    return VerifyTableStart(verifier) &&
           VerifyField<double>(verifier, VT_LOWER, 8) &&
           VerifyField<double>(verifier, VT_UPPER, 8) &&
           VerifyField<uint32_t>(verifier, VT_PATHS, 4) &&
           verifier.EndTable();
  }
  StructuredNoteHistogramBinT *UnPack(const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
  void UnPackTo(StructuredNoteHistogramBinT *_o, const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
  static ::flatbuffers::Offset<StructuredNoteHistogramBin> Pack(::flatbuffers::FlatBufferBuilder &_fbb, const StructuredNoteHistogramBinT* _o, const ::flatbuffers::rehasher_function_t *_rehasher = nullptr);
