  bool inside_bid_ask() const {
    return GetField<uint8_t>(VT_INSIDE_BID_ASK, 0) != 0;
  }
  /// model_price - mid.
  double price_error() const {
    return GetField<double>(VT_PRICE_ERROR, 0.0);
  }
