           VerifyOffsetRequired(verifier, VT_TRADE_ID) &&
           verifier.VerifyString(trade_id()) &&
           VerifyField<double>(verifier, VT_NPV, 8) &&
           VerifyField<double>(verifier, VT_NPV_PCT_OF_NOTIONAL, 8) &&
           VerifyField<double>(verifier, VT_STANDARD_ERROR, 8) &&
           VerifyField<uint32_t>(verifier, VT_PATHS, 4) &&
           VerifyField<uint64_t>(verifier, VT_SEED, 8) &&
           VerifyField<int8_t>(verifier, VT_STATUS, 1) &&
           VerifyOffset(verifier, VT_LEGS) &&
           verifier.VerifyTable(legs()) &&
           VerifyOffsetRequired(verifier, VT_EVENT_PROBABILITIES) &&
           verifier.VerifyVector(event_probabilities()) &&
           verifier.VerifyVectorOfTables(event_probabilities()) &&
           VerifyField<double>(verifier, VT_P_BARRIER_BREACH, 8) &&
           VerifyField<double>(verifier, VT_EXPECTED_LIFE_YEARS, 8) &&
           VerifyOffset(verifier, VT_GREEKS) &&
           verifier.VerifyTable(greeks()) &&
           VerifyOffsetRequired(verifier, VT_TERMS) &&
           verifier.VerifyTable(terms()) &&
           VerifyOffsetRequired(verifier, VT_SEASONING) &&
           verifier.VerifyTable(seasoning()) &&
           VerifyOffsetRequired(verifier, VT_MODEL) &&
           verifier.VerifyTable(model()) &&
           VerifyOffset(verifier, VT_MARKET) &&
           verifier.VerifyTable(market()) &&
           VerifyOffset(verifier, VT_DECOMPOSITION) &&
           verifier.VerifyTable(decomposition()) &&
           VerifyOffset(verifier, VT_CHECKS) &&
           verifier.VerifyTable(checks()) &&
           VerifyOffset(verifier, VT_DISTRIBUTION) &&
           verifier.VerifyTable(distribution()) &&
           VerifyOffset(verifier, VT_TIMING) &&
           verifier.VerifyTable(timing()) &&
           VerifyOffset(verifier, VT_VANILLA_REPRICING) &&
           verifier.VerifyTable(vanilla_repricing()) &&
           verifier.EndTable();
